import { useEffect, useRef, useState } from "react";

export interface EditableTextProps {
  value: string;
  onSave: (value: string) => Promise<void> | void;
}

export function EditableText({ value, onSave }: EditableTextProps) {
  // The value currently shown on the button. Kept locally so the label
  // reflects a successful save even if the parent passes a stable prop.
  const [current, setCurrent] = useState(value);
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(value);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    setCurrent(value);
  }, [value]);

  const buttonRef = useRef<HTMLButtonElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const refocusButton = useRef(false);

  // Return focus to the display button whenever editing ends via commit/revert.
  useEffect(() => {
    if (!editing && refocusButton.current) {
      refocusButton.current = false;
      buttonRef.current?.focus();
    }
  }, [editing]);

  const startEditing = () => {
    setDraft(current);
    setError(null);
    setEditing(true);
  };

  const revert = () => {
    setDraft(current);
    setError(null);
    setEditing(false);
    refocusButton.current = true;
  };

  const commit = async () => {
    const next = draft.trim();
    if (next === "") {
      // Reject empty commits: show an inline error and keep editing.
      setError("Value cannot be empty.");
      return;
    }
    setSaving(true);
    try {
      await onSave(next);
      setCurrent(next);
    } finally {
      setSaving(false);
      setEditing(false);
      refocusButton.current = true;
    }
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter") {
      event.preventDefault();
      void commit();
    } else if (event.key === "Escape") {
      event.preventDefault();
      revert();
    }
  };

  const handleBlur = () => {
    // Blur only commits when the value actually changed.
    if (draft !== current && draft.trim() !== "") {
      void commit();
    } else if (draft.trim() === "" && draft !== current) {
      // Emptying the field and blurring counts as a (rejected) empty commit.
      setError("Value cannot be empty.");
    } else {
      revert();
    }
  };

  if (!editing) {
    return (
      <button
        ref={buttonRef}
        type="button"
        className="editable-text"
        onClick={startEditing}
      >
        {value}
      </button>
    );
  }

  return (
    <span className="editable-text-editor">
      <input
        ref={inputRef}
        type="text"
        value={draft}
        disabled={saving}
        autoFocus
        onFocus={(event) => event.currentTarget.select()}
        aria-label="Edit value"
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? "editable-text-error" : undefined}
        onChange={(event) => {
          setDraft(event.target.value);
          if (error) setError(null);
        }}
        onKeyDown={handleKeyDown}
        onBlur={handleBlur}
      />
      {error && (
        <span id="editable-text-error" role="alert" className="editable-text-error">
          {error}
        </span>
      )}
      {saving && <span className="editable-text-saving">Saving…</span>}
    </span>
  );
}

export default EditableText;

